## 7.5 Combining Bullet Chart and Sparklines



::: {.cell}

```{.r .cell-code  code-fold="true" code-summary="Prepare the relevant tables"}
bullet <- coffeechain %>%
  filter(Date >= "2013-01-01") %>%
  group_by(`Product`) %>%
  summarise(`Target` = sum(`Budget Sales`),
            `Actual` = sum(`Sales`)) %>%
  ungroup() 

sales_data = sales_data %>%
  left_join(bullet)
```
:::

::: {.cell}

```{.r .cell-code  code-fold="true" code-summary="Combine bullet chart and sparklines"}
sales_data %>%
  gt() %>%
  gt_plt_sparkline('Monthly Sales') %>%
  gt_plt_bullet(column = Actual, 
                target = Target, 
                width = 28,
                palette = c("lightblue", 
                          "black")) %>%
  gt_theme_538()
```

